async function runPeopleDirectory(config) {
  const people = await loadPeopleProfiles();
  if (people.length === 0) {
    await Shared.showError("No people yet. Start a conversation first.");
    return;
  }

  const choice = await Shared.presentTableMenu({
    title: "People",
    subtitle: `${people.length} profile${people.length === 1 ? "" : "s"}`,
    sections: [
      {
        rows: people.map((person, index) => ({
          id: String(index),
          title: person.name,
          subtitle: [
            person.stats?.conversationCount
              ? `${person.stats.conversationCount} chats`
              : "0 chats",
            person.metadata?.languages?.length
              ? person.metadata.languages.join(", ")
              : null
          ]
            .filter(Boolean)
            .join(" · "),
          symbol: "person.crop.circle",
          disclosure: true
        }))
      }
    ]
  });

  if (choice == null) {
    return;
  }
  await openPersonProfile(people[Number(choice)], config);
}

async function openPersonProfile(person, config) {
  const sessions = (await Conversation.loadAllSessions()).filter(
    (s) => s.person.id === person.id || s.person.name === person.name
  );

  const choice = await Shared.presentTableMenu({
    title: person.name,
    subtitle: person.stats?.lastSeen
      ? `Last seen ${Shared.formatDate(person.stats.lastSeen)}`
      : "Profile",
    sections: [
      {
        rows: [
          {
            id: "chats",
            title: "Conversations",
            subtitle: `${sessions.length} saved`,
            symbol: "bubble.left.and.bubble.right",
            disclosure: true
          },
          {
            id: "edit",
            title: "Edit Profile",
            subtitle: person.metadata?.notes
              ? person.metadata.notes.slice(0, 48)
              : "Notes, country, languages",
            symbol: "pencil"
          }
        ]
      }
    ]
  });

  if (!choice) {
    return;
  }

  if (choice === "chats") {
    if (sessions.length === 0) {
      await Shared.showError("No conversations for this person.");
      return;
    }
    await browseFiltered(
      person.name,
      (s) => s.person.id === person.id || s.person.name === person.name
    );
  } else if (choice === "edit") {
    await editPersonProfile(person, config);
  }
}

async function editPersonProfile(person, config) {
  const country = await Shared.promptForText(
    "Country",
    "Optional country.",
    person.metadata?.country || ""
  );
  if (country === null) {
    return;
  }
  const notes = await Shared.promptForText(
    "Notes",
    "Profile notes.",
    person.metadata?.notes || ""
  );
  if (notes === null) {
    return;
  }
  const languages = await Shared.promptForText(
    "Languages",
    "Comma-separated language codes (e.g. ES, EN).",
    (person.metadata?.languages || [
      config.languages.conversation,
      config.languages.primary
    ]).join(", ")
  );
  if (languages === null) {
    return;
  }

  person.metadata = person.metadata || {};
  person.metadata.country = country.trim();
  person.metadata.notes = notes.trim();
  person.metadata.languages = languages
    .split(",")
    .map((l) => l.trim())
    .filter(Boolean);
  await upsertPerson(person);
  await Shared.showSuccess("Saved", `${person.name} updated.`);
}

async function loadPeopleProfiles() {
  const data = await Shared.loadJSON(Shared.PEOPLE_FILE);
  const people = Array.isArray(data) ? data : [];
  return people.map((p) => ({
    ...p,
    metadata: p.metadata || { languages: [], country: "", notes: "" },
    stats: p.stats || { conversationCount: 0, lastSeen: null }
  }));
}

async function upsertPerson(person) {
  const people = await loadPeopleProfiles();
  const idx = people.findIndex((p) => p.id === person.id);
  if (idx === -1) {
    people.push(person);
  } else {
    people[idx] = person;
  }
  await Shared.saveJSON(Shared.PEOPLE_FILE, people);
}

async function touchPersonFromSession(session) {
  const people = await loadPeopleProfiles();
  let person = people.find((p) => p.id === session.person.id);
  if (!person) {
    person = {
      id: session.person.id,
      name: session.person.name,
      createdAt: new Date().toISOString(),
      metadata: { languages: [], country: "", notes: "" },
      stats: { conversationCount: 0, lastSeen: null }
    };
    people.push(person);
  }

  const sessions = await Conversation.loadAllSessions();
  const theirs = sessions.filter(
    (s) =>
      s.person.id === session.person.id || s.person.name === session.person.name
  );

  person.stats = person.stats || {};
  person.stats.lastSeen =
    session.session.endedAt || session.session.lastActivityAt;
  person.stats.conversationCount = Math.max(theirs.length, 1);
  person.metadata = person.metadata || {};
  person.metadata.languages = Shared.unique([
    ...(person.metadata.languages || []),
    session.languages?.primary,
    session.languages?.conversation
  ]);
  await Shared.saveJSON(Shared.PEOPLE_FILE, people);
}

// ============================================================
// EXPORT
// ============================================================

async function exportFromLibrary() {
  const sessions = (await Conversation.loadAllSessions()).map(ensureProFields);
  if (sessions.length === 0) {
    await Shared.showError("No conversations to export.");
    return;
  }

  const choice = await Shared.presentTableMenu({
    title: "Export Conversation",
    subtitle: "Choose a conversation",
    sections: [
      {
        rows: sessions.map((session, index) => ({
          id: String(index),
          title: session.person.name,
          subtitle: Shared.formatDate(session.session.startedAt),
          symbol: "square.and.arrow.up",
          disclosure: true
        }))
      }
    ]
  });
  if (choice == null) {
    return;
  }
  await exportSessionInteractive(sessions[Number(choice)]);
}

async function exportSessionInteractive(session) {
  const formatChoice = await Shared.presentTableMenu({
    title: "Export Format",
    sections: [
      {
        rows: [
          { id: "md", title: "Markdown", symbol: "doc.richtext" },
          { id: "json", title: "JSON", symbol: "curlybraces" },
          { id: "txt", title: "Plain Text", symbol: "doc.plaintext" },
          { id: "html", title: "HTML", symbol: "chevron.left.forwardslash.chevron.right" }
        ]
      }
    ]
  });
  if (!formatChoice) {
    return;
  }
  const path = await exportSession(session, formatChoice);
  Pasteboard.copy(path);
  await Shared.showSuccess(
    "Exported",
    `Saved to:\n${path}\n\nPath copied to clipboard.`
  );
}

function getExportsDirectory() {
  const fm = Shared.getFileManager();
  const directory = fm.joinPath(Shared.getAppDirectory(), EXPORTS_DIRECTORY);
  if (!fm.fileExists(directory)) {
    fm.createDirectory(directory, true);
  }
  return directory;
}

async function exportSession(session, format) {
  const fm = Shared.getFileManager();
  const safeName = `${session.person.name}_${session.session.id}`
    .replace(/[^\w\-]+/g, "_")
    .slice(0, 80);
  const filename = `${safeName}.${format}`;
  const path = fm.joinPath(getExportsDirectory(), filename);

  let body = "";
  if (format === "json") {
    const clean = JSON.parse(JSON.stringify(session));
    delete clean._filePath;
    body = JSON.stringify(clean, null, 2);
  } else if (format === "md") {
    body = toMarkdown(session);
  } else if (format === "html") {
    body = toHtml(session);
  } else {
    body = toPlainText(session);
  }

  fm.writeString(path, body);
  return path;
}

function toPlainText(session) {
  const lines = [
    session.metadata?.title || "Untitled Conversation",
    `Person: ${session.person.name}`,
    `Started: ${session.session.startedAt}`,
    `Ended: ${session.session.endedAt || ""}`,
    `Turns: ${session.session.turnCount}`,
    ""
  ];
  if (session.intelligence?.summary) {
    lines.push("SUMMARY", session.intelligence.summary, "");
  }
  for (const turn of session.turns || []) {
    const speaker = turn.speaker === "me" ? "ME" : session.person.name;
    lines.push(`[${turn.timestamp}] ${speaker}`);
    lines.push(turn.sourceText);
    lines.push(`→ ${turn.translatedText}`);
    lines.push("");
  }
  return lines.join("\n");
}

function toMarkdown(session) {
  const lines = [
    `# ${session.metadata?.title || "Conversation"}`,
    "",
    `- **Person:** ${session.person.name}`,
    `- **Started:** ${session.session.startedAt}`,
    `- **Turns:** ${session.session.turnCount}`,
    ""
  ];
  if (session.intelligence?.summary) {
    lines.push("## Summary", "", session.intelligence.summary, "");
  }
  lines.push("## Transcript", "");
  for (const turn of session.turns || []) {
    const speaker = turn.speaker === "me" ? "Me" : session.person.name;
    lines.push(`### ${speaker} · ${turn.timestamp}`, "", turn.sourceText, "");
    lines.push(`> ${turn.translatedText}`, "");
  }
  return lines.join("\n");
}

function toHtml(session) {
  const esc = (s) =>
    String(s || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  const turns = (session.turns || [])
    .map((turn) => {
      const speaker = turn.speaker === "me" ? "Me" : session.person.name;
      return `<article><h3>${esc(speaker)} <small>${esc(turn.timestamp)}</small></h3><p>${esc(turn.sourceText)}</p><blockquote>${esc(turn.translatedText)}</blockquote></article>`;
    })
    .join("\n");
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${esc(session.metadata?.title || "Conversation")}</title>
<style>body{font-family:-apple-system,BlinkMacSystemFont,sans-serif;max-width:720px;margin:2rem auto;padding:0 1rem;line-height:1.45} blockquote{border-left:3px solid #888;margin-left:0;padding-left:1rem;color:#333}</style>
</head><body>
<h1>${esc(session.metadata?.title || "Conversation")}</h1>
<p><strong>${esc(session.person.name)}</strong> · ${esc(session.session.startedAt)}</p>
${session.intelligence?.summary ? `<section><h2>Summary</h2><pre>${esc(session.intelligence.summary)}</pre></section>` : ""}
<section><h2>Transcript</h2>${turns}</section>
</body></html>`;
}


// SmartTranslatePro.js
//
// SmartTranslate Pro — lean Scriptable entry.
//
// Home:
//   Translate › · Conversation · Library · People · Settings
//
// Keep: search/favorites/export, people, light post-session summary
// Dropped from UI: Insights (timeline/stats/learning/voices), long end wizard
//
// Requires (modular) or paste scripts/dist/SmartTranslatePro.js
//
// Version: 1.1.0-lean

async function main() {
  let config = await Shared.loadConfig();

  if (!config || !config.version) {
    const isFirstRun = !config;
    config = await runSetupWizard(isFirstRun, null);
    if (!config) {
      return;
    }
    await Shared.saveConfig(config);
    if (isFirstRun) {
      await Shared.showSuccess(
        "Setup Complete",
        "SmartTranslate Pro is ready."
      );
      return;
    }
  }

  // Stay in the home UITable until the user dismisses it.
  while (true) {
    const action = await showMainMenu(config);
    if (!action || action === "cancel") {
      break;
    }
    await runProAction(action, config);
    config = (await Shared.loadConfig()) || config;
  }
}

async function runProAction(action, config) {
  switch (action) {
    case "type":
      await runType(config);
      break;
    case "paste":
      await runPaste(config);
      break;
    case "dictate":
      await runDictate(config);
      break;
    case "conversation":
      await Conversation.runConversation(config, {
        onCompleted: Pro.processCompletedSession
      });
      break;
    case "library":
      await Pro.runLibrary(config);
      break;
    case "people":
      await Pro.runPeopleDirectory(config);
      break;
    case "settings": {
      const newConfig = await runSetupWizard(false, config);
      if (newConfig) {
        await Shared.saveConfig(newConfig);
      }
      break;
    }
    default:
      break;
  }
}

// ============================================================
// HOME MENU
// ============================================================

async function showMainMenu(config) {
  const engine = config.speech.engine === "apple" ? "Apple" : "ElevenLabs";
  const pair = `${Shared.getLanguageDisplayName(config.languages.primary)} ↔ ${Shared.getLanguageDisplayName(config.languages.conversation)}`;

  while (true) {
    const choice = await Shared.presentTableMenu({
      title: "SmartTranslate Pro",
      subtitle: `${pair} · ${engine}`,
      sections: [
        {
          header: "Translate",
          rows: [
            {
              id: "translate",
              title: "Quick Translate",
              subtitle: "Type, paste, or dictate",
              symbol: "character.bubble",
              disclosure: true
            },
            {
              id: "conversation",
              title: "Conversation",
              subtitle: "Multi-turn with a person",
              symbol: "person.2"
            }
          ]
        },
        {
          header: "Review",
          rows: [
            {
              id: "library",
              title: "Library",
              subtitle: "Search, favorites, export",
              symbol: "books.vertical"
            },
            {
              id: "people",
              title: "People",
              subtitle: "Profiles and past chats",
              symbol: "person.crop.circle"
            }
          ]
        },
        {
          header: "App",
          rows: [
            {
              id: "settings",
              title: "Settings",
              subtitle: "Languages, keys, speech",
              symbol: "gearshape"
            }
          ]
        }
      ]
    });

    if (!choice) {
      return "cancel";
    }

    if (choice === "translate") {
      const nested = await showTranslateMenu();
      if (!nested) {
        continue;
      }
      return nested;
    }

    return choice;
  }
}

async function showTranslateMenu() {
  return await Shared.presentTableMenu({
    title: "Quick Translate",
    subtitle: "One shot",
    sections: [
      {
        rows: [
          {
            id: "type",
            title: "Type",
            subtitle: "Enter text",
            symbol: "keyboard"
          },
          {
            id: "paste",
            title: "Paste",
            subtitle: "From clipboard",
            symbol: "doc.on.clipboard"
          },
          {
            id: "dictate",
            title: "Dictate",
            subtitle: "Speak to translate",
            symbol: "mic"
          }
        ]
      }
    ]
  });
}

// ============================================================
// ONE-SHOT
// ============================================================

async function runType(config) {
  const text = await Shared.promptForText(
    "Type",
    "Enter the text to translate."
  );
  if (text === null) {
    return;
  }
  await Shared.runOneShot(text, config);
}

async function runPaste(config) {
  const text = Pasteboard.paste() || "";
  if (!text.trim()) {
    await Shared.showError("Clipboard is empty.");
    return;
  }
  await Shared.runOneShot(text, config);
}

async function runDictate(config) {
  try {
    const text = await Shared.dictateText(config);
    if (!text || !text.trim()) {
      await Shared.showError("No speech was captured.");
      return;
    }
    await Shared.runOneShot(text, config);
  } catch (error) {
    await Shared.showError(
      `Dictation failed.\n\n${error?.message || "Unknown error."}`
    );
  }
}

// ============================================================
// SETUP
// ============================================================

async function runSetupWizard(isFirstRun, existingConfig) {
  let config = Shared.deepMerge(Shared.DEFAULT_CONFIG, existingConfig || {});

  if (isFirstRun) {
    const welcome = new Alert();
    welcome.title = "Welcome to SmartTranslate Pro";
    welcome.message =
      "Lean Pro: translate, conversations, library, and people — with a cleaner Scriptable UI.";
    welcome.addAction("Start Setup");
    await welcome.present();
  }

  const deeplKey = await Shared.configureSecret(
    "DeepL API Key",
    Shared.DEEPL_KEYCHAIN_KEY,
    "Enter your DeepL API key from https://www.deepl.com/your-account/keys\n\n(API Developer plan — Free API is no longer sold for new accounts.)"
  );
  if (!deeplKey) {
    return null;
  }

  config.languages.primary = await Shared.chooseLanguage(
    "Your Primary Language",
    "What is your primary language?",
    config.languages.primary
  );
  if (!config.languages.primary) {
    return null;
  }

  config.languages.conversation = await Shared.chooseLanguage(
    "Conversation Language",
    "What language are you translating with?",
    config.languages.conversation,
    [config.languages.primary]
  );
  if (!config.languages.conversation) {
    return null;
  }

  config.languages.defaultTarget = await Shared.chooseLanguage(
    "Default Translation Target",
    "When the input is not already this language, translate to:",
    config.languages.defaultTarget
  );
  if (!config.languages.defaultTarget) {
    return null;
  }

  const dictationOptions = [
    "Automatic",
    ...Shared.LANGUAGE_OPTIONS.map((lang) => `${lang.name} (${lang.code})`)
  ];
  const dictationChoice = await Shared.chooseFromList(
    "Dictation Language",
    dictationOptions,
    "Language hint for Dictate."
  );
  if (dictationChoice === -1) {
    return null;
  }
  config.input.dictationLanguage =
    dictationChoice === 0
      ? "auto"
      : Shared.LANGUAGE_OPTIONS[dictationChoice - 1].code;

  const engineChoice = await Shared.chooseFromList(
    "Speech Engine",
    ["Apple Native Voice", "ElevenLabs (requires API key)"],
    "Choose how translations are spoken."
  );
  if (engineChoice === -1) {
    return null;
  }
  config.speech.engine = engineChoice === 0 ? "apple" : "elevenlabs";

  if (config.speech.engine === "apple") {
    config.speech.apple.rate = await Shared.chooseSlider(
      "Apple Speech Rate",
      config.speech.apple.rate,
      0.1,
      1.0
    );
  } else {
    const elevenLabsKey = await Shared.configureSecret(
      "ElevenLabs API Key",
      Shared.ELEVENLABS_KEYCHAIN_KEY,
      "Enter your ElevenLabs API key."
    );
    config.speech.elevenlabs.enabled = !!elevenLabsKey;

    if (config.speech.elevenlabs.enabled) {
      const voiceResult = await configureElevenLabsVoices(
        config,
        elevenLabsKey
      );
      if (!voiceResult) {
        return null;
      }
      config.speech.elevenlabs.voices = voiceResult;
    }
  }

  const shouldTest = await Shared.chooseBoolean(
    "Test Configuration",
    "Test translation and speech now?",
    true
  );
  if (shouldTest) {
    await testConfiguration(config);
  }

  return config;
}

async function configureElevenLabsVoices(config, elevenLabsKey) {
  const languages = Shared.unique([
    config.languages.primary,
    config.languages.conversation,
    config.languages.defaultTarget
  ]);
  const newVoices = { ...config.speech.elevenlabs.voices };

  let allApiVoices;
  try {
    allApiVoices = await Shared.fetchElevenLabsVoices(elevenLabsKey);
  } catch (error) {
    await Shared.showError(
      `Could not load ElevenLabs voices.\n\n${error?.message || "Unknown error."}`
    );
    return null;
  }

  for (const langCode of languages) {
    const langName = Shared.getLanguageDisplayName(langCode);
    const compatibleVoices = allApiVoices
      .filter((v) => {
        const supported =
          v.labels?.language?.toLowerCase() ===
          langCode.slice(0, 2).toLowerCase();
        const isMultilingual =
          v.category === "premade" &&
          v.name.toLowerCase().includes("multilingual");
        return supported || isMultilingual;
      })
      .slice(0, Shared.MAX_VOICE_RESULTS);

    if (compatibleVoices.length === 0) {
      continue;
    }

    const labels = compatibleVoices.map((v) => v.name);
    const choice = await Shared.chooseFromList(`${langName} AI Voice`, labels);
    if (choice === -1) {
      continue;
    }

    const selected = compatibleVoices[choice];
    newVoices[langCode] = {
      voiceId: selected.voice_id,
      name: selected.name
    };
  }

  return newVoices;
}

async function testConfiguration(config) {
  const testText = await Shared.promptForText(
    "Configuration Test",
    "Enter a short sentence to test translation and speech.",
    "Hello, world!"
  );
  if (!testText) {
    return;
  }

  try {
    const deeplKey = Shared.getRequiredKey(
      Shared.DEEPL_KEYCHAIN_KEY,
      "DeepL"
    );
    const { translation, detectedLanguage, targetLanguage } =
      await Shared.translateWithDeepL(testText, deeplKey, config.languages);

    const summary = `Detected: ${detectedLanguage}\nTarget: ${targetLanguage}\n\n${translation}`;
    const alert = new Alert();
    alert.title = "Translation Test";
    alert.message = summary;
    alert.addAction("OK");
    alert.addAction("Speak");
    const choice = await alert.presentAlert();
    if (choice === 1) {
      await Shared.speakTranslation(translation, targetLanguage, config);
    }
  } catch (error) {
    await Shared.showError(
      `Configuration test failed.\n\n${error?.message || "Unknown error."}`
    );
  }
}

await main();
Script.complete();
